func wordBreak(_ s: String, _ wordDict: [String]) -> Bool {
    let a = Array(s), words = Set(wordDict), maxLen = wordDict.map(\.count).max() ?? 0
    var dp = [Bool](repeating: false, count: a.count + 1)
    dp[0] = true
    for i in stride(from: 1, through: a.count, by: 1) {
        for j in stride(from: i - 1, through: max(0, i - maxLen), by: -1) where dp[j] {
            if words.contains(String(a[j..<i])) { dp[i] = true; break }
        }
    }
    return dp[a.count]
}
